package ro.leo.visual;
import ro.leo.i18n.L;
import android.content.*;import android.graphics.*;import android.os.Bundle;import android.view.*;import android.widget.*;import java.util.*;
public final class ThemePacksActivity extends LeoActivity {
 private int selected,tab;private View previewRoot;
 protected void onCreate(Bundle b){super.onCreate(b);home();}
 private void home(){ArrayList<String> rows=new ArrayList<String>(Arrays.asList(ThemePacks.NAMES));rows.add(L.t("Restabilește aspectul anterior"));list(L.t("Colecții vizuale Leo"),rows,selected,new Choice(){public void pick(int n){if(n<ThemePacks.NAMES.length){selected=n;tab=0;preview();}else options(L.t("Restabilești culorile, fontul și fundalul?"),new String[]{L.t("Păstrează"),L.t("Restabilește")},new Choice(){public void pick(int yes){if(yes==1)worker.execute(new Runnable(){public void run(){try{ThemeCheckpoint.restore(ThemePacksActivity.this);ui(new Runnable(){public void run(){notice(L.t("Aspect restabilit"));home();}});}catch(Exception e){ui(new Runnable(){public void run(){notice(L.t("Nu există o copie vizuală validă"));}});}}});}});}},"",null);}
 private void preview(int n){selected=Math.floorMod(n,ThemePacks.NAMES.length);tab=0;preview();}
 private void preview(){final Appearance.Palette sample=new Appearance.Palette(Appearance.COLORS[ThemePacks.THEMES[selected]]);begin(ThemePacks.NAMES[selected]);previewRoot=root;root.addView(new View(this){final Paint p=new Paint(3);void box(Canvas c,int x,int y,int w,int h,int color){p.setColor(color);c.drawRoundRect(x,y,x+w,y+h,6,6,p);}void label(Canvas c,String s,int x,int y,int size,int color){p.setColor(color);p.setTextSize(size);p.setTypeface(Typeface.create("sans-serif-medium",0));c.drawText(s,x,y,p);}void badge(Canvas c,String name,int x,int y){AppBadge icon=new AppBadge(name,36);icon.setBounds(x,y,x+36,y+36);icon.draw(c);}protected void onDraw(Canvas c){c.save();c.scale(getWidth()/240f,getHeight()/224f);c.drawColor(sample.background);label(c,new String[]{L.t("ACASĂ"),"MENIU","PLAYER","BLOCARE"}[tab]+L.t(" · mostră ")+(tab+1)+"/4",10,20,14,sample.accent);if(tab==0){label(c,"12:40",18,68,36,Color.WHITE);label(c,L.t("Joi · Leo"),20,90,14,sample.accent);box(c,10,108,220,46,sample.card);label(c,L.t("Meteo · 18° · senin"),20,137,16,Color.WHITE);badge(c,L.t("Telefon"),25,168);badge(c,L.t("Mesaje"),100,168);badge(c,L.t("Muzică"),177,168);}else if(tab==1){String[] names={L.t("Telefon"),L.t("Contacte"),L.t("Mesaje"),L.t("Ceas"),L.t("Muzică"),L.t("Setări")};for(int i=0;i<6;i++){int x=14+i%3*76,y=40+i/3*82;if(i==1)box(c,x-4,y-4,69,75,sample.selection);badge(c,names[i],x+11,y);label(c,names[i],x,y+59,12,i==1?sample.ink:Color.WHITE);}}else if(tab==2){box(c,10,38,220,128,sample.card);p.setColor(sample.accent);c.drawCircle(65,96,39,p);p.setColor(sample.background);c.drawCircle(65,96,11,p);label(c,L.t("Muzică Leo"),116,86,16,Color.WHITE);label(c,L.t("Colecția ta"),116,111,12,sample.accent);box(c,15,179,210,5,sample.card);box(c,15,179,95,5,sample.accent);label(c,"01:24       ◀  ▶       03:18",20,211,13,Color.WHITE);}else{label(c,"12:40",58,104,41,Color.WHITE);label(c,L.t("LEO · telefon cu taste"),36,137,15,sample.accent);box(c,20,166,200,36,sample.card);label(c,L.t("Deblochează din taste"),35,190,14,Color.WHITE);}c.restore();}},new LinearLayout.LayoutParams(-1,0,1));left=new Runnable(){public void run(){options(L.t("Aplici colecția?"),new String[]{L.t("Păstrează stilul actual"),L.t("Pachet complet · culori, font, fundal"),L.t("Doar culori în toate aplicațiile Leo")},new Choice(){public void pick(final int yes){if(yes==0)return;worker.execute(new Runnable(){public void run(){try{ThemeCheckpoint.apply(ThemePacksActivity.this,selected,yes==1);ui(new Runnable(){public void run(){notice(L.t("Colecție aplicată · redeschide aplicațiile"));home();}});}catch(Exception e){ui(new Runnable(){public void run(){notice(L.t("Tema nu a putut fi aplicată"));}});}}});}});}};back=new Runnable(){public void run(){home();}};footer(L.t("Aplică"),L.t("← / → mostră"),L.t("Înapoi"));}
 public boolean onKeyDown(int code,KeyEvent e){if(root==previewRoot&&(code==21||code==22)){if(e.getRepeatCount()==0){tab=Math.floorMod(tab+(code==22?1:-1),4);preview();}return true;}return super.onKeyDown(code,e);}
}
